interface ButtonDownloadProps {
  variant?: 'appstore' | 'playstore';
  color?: 'light' | 'dark';
  href?: string;
  onClick?: () => void;
}

export default function ButtonDownload({
  variant = 'appstore',
  color = 'dark',
  href,
  onClick,
}: ButtonDownloadProps) {
  const className = [
    styles.button,
    styles[variant],
    styles[color],
  ].join(' ');

  const content =
    variant === 'appstore' ? (
      <>
        <AppleIcon />
        <span className={styles.label}>
          <span className={styles.labelSub}>Baixe na</span>
          <span className={styles.labelMain}>App Store</span>
        </span>
      </>
    ) : (
      <>
        <img
          src="/images/icons/Playstore.svg"
          alt=""
          width={21}
          height={24}
          aria-hidden="true"
          className={styles.playstoreIcon}
        />
        <span className={styles.label}>
          <span className={styles.labelSub}>Disponível no</span>
          <GooglePlayWordmark />
        </span>
      </>
    );

  if (href) {
    return (
      <a href={href} className={className}>
        {content}
      </a>
    );
  }

  return (
    <button className={className} onClick={onClick}>
      {content}
    </button>
  );
}
